import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ViewType {
  HOME = 'home',
  OPEN_SOLICITATION = 'open-solicitation',
  CONSULTATION = 'consultation',
  APPROVAL = 'approval',
  ADMISSION = 'admission'
}

export interface Solicitation {
  id: string;
  classification: string;
  vacancyId: string;
  department: string;
  status: string;
  slaStatus: string;
  slaColor: 'green' | 'red' | 'orange';
  roleName: string;
  date: string;
}

export interface Attachment {
  id: string;
  name: string;
  type: 'pdf' | 'image';
}

import React, { useState } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import HomeView from './views/HomeView';
import JobOpeningView from './views/JobOpeningView';
import ConsultationView from './views/ConsultationView';
import ApprovalView from './views/ApprovalView';
import AdmissionView from './views/AdmissionView';

const App: React.FC = () => {
  const [isDarkMode, setIsDarkMode] = useState(false);

  const toggleDarkMode = () => {
    setIsDarkMode(!isDarkMode);
    document.documentElement.classList.toggle('dark');
  };

  return (
    <HashRouter>
      <div className="flex h-screen overflow-hidden font-sans">
        <Sidebar />
        <div className="flex-1 flex flex-col min-w-0 bg-gray-50 dark:bg-gray-900">
          <Header onToggleDarkMode={toggleDarkMode} isDarkMode={isDarkMode} />
          <main className="flex-1 overflow-y-auto no-scrollbar">
            <Routes>
              <Route path="/" element={<HomeView />} />
              <Route path="/open-solicitation" element={<JobOpeningView />} />
              <Route path="/consultation" element={<ConsultationView />} />
              <Route path="/approval" element={<ApprovalView />} />
              <Route path="/admission" element={<AdmissionView />} />
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </main>
        </div>
      </div>
    </HashRouter>
  );
};

export default App;

